inputs = [{'path':path,'sha256':hashlib.sha256((ROOT/path).read_bytes()).hexdigest(),'role':'producer' if path.endswith(('.py','.pl','.sh')) else 'input'} for path in sorted(set(paths))]
statement = 'Twenty-two authored basic statement cases complete66 Toolbox inspections under hash seeds0/1/42 at3738 immutable regular Git c02 inputs plus two explicit probe/case overlays. Each run returns59 contiguous original Unicode scalar statement intervals and37 selected events with zero private origins; complete actual stdout is identical across the three seeds and outer/internal stderr is empty. Eleven repeated-contract fixtures each produce two events. Nineteen independent reason-sensitive diagnosis controls reject. Four unchanged consumers pass52 complete groups with nine controls; the original incorrect AST-suite selection/source/exit/channels are retained separately and the corrected selection is fully rerun. Three original compiler-inspection examples render from58 separately retained final publication inputs with five controls. The previous consumer claim freezes historically at exact c02 after all37 bound input hashes verify, and two prepare-producer docstrings alone are clarified.'
scope = 'Bounded default-callback source/frame diagnosis, not production source provenance implementation, arbitrary host-language coverage, custom interior-transform callback coverage, executable membership/comment semantic repair, runtime execution, DSL/backend admission or global prior-record audit closure. The author oracle assembles literal original segments and scalar offsets; it never locates source by equal raw strings. Input count is a conservative supplied-input superset, not an observed minimal IO read set. Gitlinks/non-regular entries are excluded without payload reads; all regular Git bytes are recoverable at c02ce88826f815c201a652d5b29bd3cf044d2740, and the two exact overlays are retained. Every actual run has contents/modes/population checks before and after execution. Original exploratory six-case stdout retains its derived runtime callback locator losslessly and is not promoted to fixed-input acceptance. Read-only host OS/Perl/standard libraries and PATH-resolved prove/mdBook are necessary external execution prerequisites; consumer/render executable SHA identities are observed separately, no cross-host byte-identical transcript claim. Project-owned scratch/output stays on the repository filesystem. Private frames, eleven producer hooks and canonical statement-family acceptance are owned by .1/.2/.3; sibling twenty-contract composition and broader audit remain open.'
record={'version':1,'owner':OWNER,'claims':[{
 'name':'default-basic-statement-contiguous-source-diagnosis','statement':statement,'scope':scope,
 'rederive':{'status':'checked','command':'bash tools/run_python_project_data.sh '+PREFIX+'capture.py; bash tools/run_python_project_data.sh '+PREFIX+'review.py; bash tools/run_python_project_data.sh '+PREFIX+'consumers.py; bash tools/run_python_project_data.sh '+PREFIX+'consumer-review.py; bash tools/run_python_project_data.sh '+PREFIX+'freeze-review.py; bash tools/run_python_project_data.sh '+PREFIX+'book.py --review',
             'granularity':'Every3738 immutable Git object/mode/hash and two explicit overlay identities; each actual per-run input boundary and full channel; all22 authored original scalar segment constructions,59 statement spans/37 events per run, exact selected contract/order/private result and complete Toolbox fields; four complete ordered positive TAP plans; complete final58-book-input capsule and original three rendered examples.','result':statement},
 'falsify':{'status':'checked','hypothesis':'Comment stripping, joining comment-separated tokens, choosing quoted equal text, reusing repeated occurrences, byte offsets, missing input/source/instrument/channels or partial tests could produce misleading source-frame acceptance.',
            'oracle':'Independent literal-segment construction and scalar offsets, original statement/event occurrence indices; immutable Git membership/object/SHA256/mode census; exact full channels and actual producer hashes; complete ordered TAP plans including nested failures; independent literal examples in rendered HTML.',
            'red_control':'Nineteen reason-checked diagnosis corruptions reject event deletion, invented origins/nested events, stripped/joined comments, forged contract dependencies, quoted/Unicode/repeated interval errors, missing or changed Git inputs/modes, promoted partial reports, forged instruments/guards/exits/channels. Nine consumer corruptions reject missing/partial suites, changed instruments/guards/exits/channels, failed nested TAP, truncated reach and absent prove completion. Five render corruptions reject failed renders, missing guards, forged producer/HTML channels and missing actual examples. Actual incorrect suite-name failure remains incomplete with original source/channels, then the correctly named four unchanged suites complete52 groups.'},
 'durability':{'status':'checked','mode':'live','inputs':inputs}
}]}
target=ROOT/'docs/claims'/(OWNER+'.json');target.write_text(json.dumps(record,indent=2)+'\n');assert target.stat().st_size<=131072
